(() => {
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let state=null,controller=null,request=0,lookupTimer=null;const profileCache=new Map();
const total=()=>state.items.reduce((n,p)=>n+Math.round(p.price*100)*p.qty,0)/100;
const summary=()=>`<div class="co-items">${state.items.map(p=>`<div><span>${esc(p.name)}<small>${p.qty} ${p.qty===1?'unidade':'unidades'} × ${money(p.price)}</small></span><b>${money(Math.round(p.price*100)*p.qty/100)}</b></div>`).join('')}</div><div class="co-total"><span>Total</span><strong>${money(total())}</strong></div>`;
function show(html){window.lojaCart.open(`<div class="co-checkout">${html}</div>`,'checkout');const title=document.querySelector('.co-checkout h2');if(title){title.tabIndex=-1;title.focus({preventScroll:true})}}
function details(){clearTimeout(lookupTimer);request++;controller?.abort();show(`<span class="eyebrow">1 DE 2 · SEUS DADOS</span><h2>Finalizar compra</h2><p>Informe seu e-mail e a conta Roblox que receberá o pedido.</p>${summary()}<form id="co-form"><label for="co-email">E-mail<input id="co-email" type="email" name="email" required maxlength="254" autocomplete="email" placeholder="voce@exemplo.com" value="${esc(state.email||'')}"></label><label for="co-username">Nome de usuário Roblox<div class="co-user-input"><span>@</span><input id="co-username" name="username" required minlength="1" maxlength="20" pattern="[A-Za-z0-9_]{1,20}" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Seu nome de usuário" value="${esc(state.username||'')}"></div></label><small>Use o nome de usuário, não o nome de exibição. Nunca pedimos senha Roblox. O avatar aparece automaticamente ao terminar de digitar.</small><button type="button" class="co-lookup" data-co-lookup>Buscar novamente</button><div id="co-profile" role="status"></div><label class="co-confirm"><input type="checkbox" name="confirmed" required>Conferi o e-mail e o usuário Roblox informados.</label><p class="co-error" id="co-error" role="alert"></p><button class="button" type="submit">Revisar pedido →</button></form><p class="co-local">${window.paymentUI?.enabled?'Seu e-mail será utilizado na cobrança pela PurinCash. Nunca pedimos senha Roblox.':'Este fluxo registra um pedido local de demonstração. Nenhum pagamento ou e-mail será enviado.'}</p>`);scheduleLookup()}
function review(){clearTimeout(lookupTimer);request++;controller?.abort();show(`<span class="eyebrow">2 DE 2 · REVISÃO</span><h2>Confira seu pedido</h2><div class="co-customer"><span>E-mail<b>${esc(state.email)}</b></span><span>Conta Roblox<b>@${esc(state.username)}</b></span></div>${summary()}<p class="co-local">${window.paymentUI?.enabled?'Confira os dados e o total. Ao continuar será gerada uma cobrança PIX pela PurinCash. A entrega dos produtos é acompanhada separadamente.':'Confira os dados antes de confirmar. Este pedido não gera cobrança ou entrega real.'}</p><button class="button" data-co-confirm>${window.paymentUI?.enabled?'Gerar PIX para pagamento':'Confirmar pedido de demonstração'}</button><button class="co-back" data-co-back>← Corrigir meus dados</button>`)}
async function confirm(){if(!state||state.complete)return;if(window.paymentUI?.enabled){if(state.paymentAttempted)return;state.paymentAttempted=true;const b=document.querySelector('[data-co-confirm]');b.disabled=true;b.textContent='Gerando PIX…';try{await window.paymentUI.create(state);state.complete=true}catch(e){const error=document.createElement('p');error.className='co-payment-error';error.setAttribute('role','alert');error.textContent=e.message;document.querySelector('.co-checkout')?.append(error);b.textContent='Solicitação encerrada — confira o painel antes de repetir'}return;}state.complete=true;const order={id:'STB-'+Date.now().toString(36).toUpperCase()+'-'+crypto.randomUUID().slice(0,4).toUpperCase(),createdAt:new Date().toISOString(),email:state.email,robloxUsername:state.username,items:state.items,total:total(),status:'demonstracao'};let saved=false;try{let orders=JSON.parse(sessionStorage.getItem('local-orders')||'[]');if(!Array.isArray(orders))orders=[];sessionStorage.setItem('local-orders',JSON.stringify([...orders.slice(-9),order]));saved=true}catch{}state.onConfirmed?.();show(`<div class="co-success">✓</div><span class="eyebrow">PEDIDO DE DEMONSTRAÇÃO</span><h2>Pedido confirmado</h2><p class="co-order-id">${esc(order.id)}</p><div class="co-customer"><span>E-mail<b>${esc(order.email)}</b></span><span>Conta Roblox<b>@${esc(order.robloxUsername)}</b></span></div>${summary()}<p class="co-local">${saved?'O registro está salvo nesta sessão do navegador.':'O registro está disponível nesta tela.'} Nenhum e-mail foi enviado, pagamento cobrado ou entrega realizada.</p><a class="button" href="/meus-pedidos">Ver meus pedidos →</a><button class="co-back" data-close>Continuar comprando</button>`)}
function profileMarkup(p){let image='';try{const u=new URL(p.avatarUrl);if(u.protocol==='https:'&&(u.hostname==='rbxcdn.com'||u.hostname.endsWith('.rbxcdn.com')))image=`<img src="${esc(u.href)}" alt="Avatar de ${esc(p.username)}" referrerpolicy="no-referrer">`}catch{}return `<div class="co-public-profile">${image||'<span class="co-avatar-placeholder" aria-label="Avatar indisponível">♙</span>'}<div><b>${esc(p.displayName||p.username)}</b><span>@${esc(p.username)}</span><a href="https://www.roblox.com/users/${p.id}/profile" target="_blank" rel="noopener noreferrer">Ver perfil ↗</a></div></div><small>Confira se esta é a conta desejada.</small>`}
function scheduleLookup(){clearTimeout(lookupTimer);const input=document.querySelector('#co-username');if(!input||!/^[A-Za-z0-9_]{3,20}$/.test(input.value.trim()))return;lookupTimer=setTimeout(()=>lookup(),850)}
async function lookup(){clearTimeout(lookupTimer);const input=document.querySelector('#co-username');if(!input)return;const username=input.value.trim();if(!/^[A-Za-z0-9_]{1,20}$/.test(username))return;const token=++request;controller?.abort();controller=new AbortController();const button=document.querySelector('[data-co-lookup]'),box=document.querySelector('#co-profile');button.disabled=true;button.textContent='Buscando perfil…';box.setAttribute('aria-busy','true');box.textContent='Carregando avatar e perfil Roblox…';try{let p;const cached=profileCache.get(username.toLowerCase());if(cached&&Date.now()-cached.time<300000)p=cached.profile;else{const response=await fetch('/api/roblox/user?username='+encodeURIComponent(username),{signal:controller.signal,headers:{Accept:'application/json'}});if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Reinicie o servidor para ativar a busca Roblox.');p=await response.json();if(!response.ok)throw Error(p.error||'Não foi possível buscar o perfil.');if(!Number.isSafeInteger(p.id)||!/^[A-Za-z0-9_]{1,20}$/.test(p.username))throw Error('Perfil inválido.');profileCache.set(username.toLowerCase(),{time:Date.now(),profile:p})}if(token!==request||!box.isConnected)return;state.profile=p;box.innerHTML=profileMarkup(p)}catch(e){if(e.name!=='AbortError'&&token===request&&box.isConnected)box.textContent=e.message==='Failed to fetch'?'Não foi possível consultar agora. Confira seu usuário e tente novamente.':e.message}finally{if(token===request&&button.isConnected){button.disabled=false;button.textContent='Buscar novamente';box.removeAttribute('aria-busy')}}}

document.addEventListener('submit',e=>{if(e.target.id!=='co-form')return;e.preventDefault();if(!e.target.reportValidity())return;state.email=e.target.elements.email.value.trim();state.username=e.target.elements.username.value.trim();review()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-co-lookup'))lookup(b);if(b.hasAttribute('data-co-back'))details();if(b.hasAttribute('data-co-confirm'))confirm()});
document.addEventListener('input',e=>{if(e.target.id==='co-username'){request++;controller?.abort();state.profile=null;const box=document.querySelector('#co-profile');box.textContent='';box.removeAttribute('aria-busy');const button=document.querySelector('[data-co-lookup]');button.disabled=false;button.textContent='Buscar novamente';scheduleLookup()}if(e.target.matches('#co-username,#co-email')){const checkbox=document.querySelector('#co-form input[name=confirmed]');if(checkbox)checkbox.checked=false}});
document.querySelector('#modal').addEventListener('close',()=>{clearTimeout(lookupTimer);request++;controller?.abort()});
window.checkoutFlow={async open(items,onConfirmed){if(!items.length)return;window.lojaCart.open('<div class="co-loading" role="status"><span class="eyebrow">SEU PEDIDO</span><h2>Preparando checkout…</h2><p>Aguarde um instante.</p></div>','checkout');await window.paymentUI?.ready;if(!document.querySelector('.co-loading')||!document.querySelector('#modal')?.open)return;if(window.paymentUI?.unavailable){window.lojaCart.open('<div class="co-checkout"><h2>Pagamento indisponível</h2><p>Não foi possível habilitar o pagamento agora. Tente novamente mais tarde.</p><button class="button" data-close>Voltar ao carrinho</button></div>','checkout');return}let username='';try{const p=JSON.parse(localStorage.getItem('selected-roblox-profile'));if(/^[A-Za-z0-9_]{1,20}$/.test(p?.username))username=p.username}catch{}state={items:items.map(p=>({...p})),onConfirmed,username,email:(()=>{try{return JSON.parse(localStorage.getItem('account-preferences')||'{}').email||''}catch{return ''}})(),complete:false};details()}};
})();
